  "claims": [
    {
      "claim": "Instruction that increases an existing employee’s job skills is training.",
      "basis": "excerpt"
    },
    {
      "claim": "Training is included in the combined activity, training and development.",
      "basis": "excerpt"
    },
    {
      "claim": "The source defines training as increasing employees’ aptitudes, skills and abilities to perform specific jobs.",
      "basis": "excerpt"
    }
  ],
  "passed": false,
  "reasons": [
    "The proposed explanation’s claims are supported. The blind distractor rationales, however, add definitions not established by the supplied evidence."
  ],
  "evidence_ids": [
    "E1.1",
    "E2.3"
  ],
  "resolution_audit": {
    "key": "A",
    "key_fully_supported": true,
    "key_reason": "The job-skill instruction matches E1.1; preparation for greater responsibility signals development, and E2.3 names Training and Development as a syllabus topic.",
    "distractors": [
      {
        "option": "B",
        "refutation_entailed": false,
        "basis": "unsupported",
        "reason": "Neither the stem nor excerpts define recruitment or establish that incumbent instruction cannot also occur alongside recruitment."
      },
      {
        "option": "C",
        "refutation_entailed": false,
        "basis": "unsupported",
        "reason": "The stem says the employee is already doing the job, but the evidence does not define placement or rule out earlier placement."
      },
      {
        "option": "D",
        "refutation_entailed": false,
        "basis": "unsupported",
        "reason": "No supplied excerpt defines compensation; the stem’s silence about pay alone does not establish a categorical refutation."
      }
    ]
  }
}
